import type { Ref } from "vue";
import { sql } from "kysely";
import { rdb } from "@/shared/database";
import { useReactiveQuery } from "@/shared/composables/useReactiveQuery";
import { warehouseRepo } from "@/domains/core";
import { FALLBACK_REORDER_POINT, healthFor, movementKind, signedQty } from "../stock.format";
import type { StockProductDetail, StockMovementItem, StockLocationLevel } from "../stock.types";

export function useStockProduct(productRuid: Ref<string | null>) {
  const { data, loading, refetch } = useReactiveQuery<StockProductDetail | null>(
    async () => {
      const ruid = productRuid.value;
      if (!ruid) return null;

      const product = await rdb
        .selectFrom("product_product as p")
        .leftJoin("product_template as t", "t._ruid", "p.product_tmpl_id")
        .leftJoin("product_category as c", "c._ruid", "t.categ_id")
        .select([
          "p._ruid as ruid",
          "p.name as name",
          "p.default_code as sku",
          "p._write_date as writeDate",
          "c.name as categName",
        ])
        .where("p._ruid", "=", ruid)
        .executeTakeFirst();
      if (!product) return null;

      const quantRow = await rdb
        .selectFrom("stock_quant")
        .select([
          sql<number>`coalesce(sum(quantity),0)`.as("on_hand"),
          sql<number>`coalesce(sum(reserved_quantity),0)`.as("reserved"),
        ])
        .where("product_id", "=", ruid)
        .where("_delete_date", "is", null)
        .executeTakeFirst();
      const onHand = Number(quantRow?.on_hand ?? 0);
      const reserved = Number(quantRow?.reserved ?? 0);

      const moveRows = await rdb
        .selectFrom("stock_move as m")
        .leftJoin("stock_picking as pk", "pk._ruid", "m.picking_id")
        .select([
          "m.id as id",
          "m.product_uom_qty as qty",
          "pk.operation_type as op",
          "pk.date as date",
        ])
        .where("m.product_id", "=", ruid)
        .where("m._delete_date", "is", null)
        .orderBy("pk.date", "desc")
        .limit(6)
        .execute();

      const movements: StockMovementItem[] = moveRows.map((r) => {
        const kind = movementKind(r.op ?? null);
        return {
          id: Number(r.id),
          productName: product.name,
          qty: signedQty(Number(r.qty ?? 0), kind),
          kind,
          date: r.date ?? null,
        };
      });

      const warehouses = await warehouseRepo.list({
        orderBy: { column: "name", direction: "asc" },
      });
      const mainName = warehouses[0]?.name ?? "Main Warehouse";
      const locations: StockLocationLevel[] = [
        { name: "Van", qty: null, ratio: null },
        { name: mainName, qty: onHand, ratio: 1 },
      ];

      return {
        ruid: product.ruid,
        name: product.name,
        sku: product.sku ?? null,
        category: product.categName ?? null,
        onHand,
        reorderPoint: FALLBACK_REORDER_POINT,
        reserved,
        lastSync: product.writeDate ?? null,
        locations,
        movements,
        health: healthFor(onHand),
      };
    },
    {
      tables: ["stock_quant", "stock_move", "stock_picking", "product_product"],
      queryKey: "stock:product-detail",
      refetchOn: ["insert", "update", "delete", "bulk"],
      debounce: 120,
    },
  );

  watch(productRuid, () => refetch());

  return { detail: computed(() => data.value), loading };
}
